G=load(); print(sorted(G))
TF={'v':np.flipud,'id':lambda a:a,'b':lambda a:np.fliplr(np.flipud(a)),'f':np.fliplr}
def f(inp):
    arr=np.array(inp); cnt=Counter(arr.flat)
    sep=max(set(int(v) for v in arr)-{int(cnt.most_common(1)[0][0])}, key=lambda v: len([r for r in range(arr.shape[0]) if sum(1 for c in range(arr.shape[1]) if arr[r,c]==v)>arr.shape[1]-1]))
    # simpler: sep = color of fully constant row; prefer row with all same != bg
    bg=int(cnt.most_common(1)[0][0])
    rows_const=[(r,arr[r][0]) for r in range(arr.shape[0]) if len(set(arr[r]))==1]
    cols_const=[(c,arr[:,c][0]) for c in range(arr.shape[1]) if len(set(arr[:,c]))==1]
    rs=[r for r,_ in rows_const]; cs=[c for c,_ in cols_const]
    srs=min(rs), scs=min(cs)
    sep=int(arr[srs,scs]); 
    blocks={'TL':arr[:srs,:scs],'TR':arr[:srs,scs+1:],
            'BL':arr[srs+1:,:scs],'BR':arr[srs+1:,scs+1:]}
    P=max(blocks.items(), key=lambda kv: sum(1 for v in kv[1].flat if v!=sep))[1]
    A=np.concatenate([np.concatenate([TF['v'](P),TF['id'](P)],axis=1),np.concatenate([TF['b'](P),TF['f'](P)],axis=1)],axis=0)
    cm={int(bg):int(bg)}
    for v in sorted({int(v) for v in set(arr.flat)})-{int(bg),int(sep)}:
        cm[v]=int(sep)
    return [[cm[int(v)] for v in row] for row in A.tolist()]
