from collections import Counter
np_=__import__('numpy')
def f(inp, role='r'):
    a=np_.array(inp); H,W=a.shape
    cnt=Counter(int(v) for v in a.flatten()); bg=cnt.most_common(1)[0][0]
    sr=[i for i in range(H) if len({v for v in a[i]})==1][0]
    sc=[j for j in range(W) if len({a[r,j] for r in range(H)})==1][0]
    sep=int(a[sr,sc]); pat={v for v in cnt if v!=bg and v!=sep}
    o=np_.full((H,W),bg,dtype=int)
    for i in range(H):
        for j in range(W):
            if i!=sr and j!=sc:
                r_,c_=(i if role=='r' else sr, j if role=='c' else sc)
                if int(a[r_,c_]) in pat: o[i,j]=sep
    return [[int(v) for v in row] for row in o]
